using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly HttpClient client;
    private readonly string baseUrl;

    private string? method, path, contentType, body;
    private int statusCode = 200;
    private string responseBody = """{"status":"approved"}""";

    public HttpPaymentGatewayTests()
    {
        var port = FreePort();
        baseUrl = $"http://127.0.0.1:{port}/";
        listener.Prefixes.Add(baseUrl);
        listener.Start();
        client = new HttpClient { BaseAddress = new Uri(baseUrl) };
    }

    [Fact]
    public async Task The_request_is_a_json_post_with_reference_amount_and_currency()
    {
        await Authorize("ORD-7", new Money(12.50m, "eur"));

        Assert.Equal("POST", method);
        Assert.Equal("/v1/authorizations", path);
        Assert.StartsWith("application/json", contentType);
        using var json = JsonDocument.Parse(body!);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_status_is_read_as_approved()
    {
        responseBody = """{"status":"approved"}""";
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_declined_status_is_read_as_declined()
    {
        responseBody = """{"status":"declined"}""";
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task Unknown_status_or_missing_status_is_never_treated_as_approved()
    {
        responseBody = """{"status":"pending"}""";
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());

        responseBody = """{"decision":"approved"}""";
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());

        responseBody = "null";
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task Extra_fields_in_the_response_are_ignored()
    {
        responseBody = """{"status":"approved","id":"a-1","risk":{"score":3}}""";
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_402_refusal_is_a_decline_even_when_the_body_says_approved()
    {
        statusCode = 402;
        responseBody = """{"status":"approved"}""";
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_402_refusal_with_an_empty_body_is_a_decline()
    {
        statusCode = 402;
        responseBody = "";
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_failures_surface_as_errors_rather_than_a_decision(int status)
    {
        statusCode = status;
        responseBody = """{"status":"approved"}""";
        var error = await Assert.ThrowsAsync<HttpRequestException>(Authorize);
        Assert.Equal((HttpStatusCode)status, error.StatusCode);
    }

    [Fact]
    public async Task A_malformed_body_surfaces_as_an_error()
    {
        responseBody = "<html>not json</html>";
        await Assert.ThrowsAsync<JsonException>(Authorize);
    }

    [Fact]
    public async Task A_non_string_status_surfaces_as_an_error()
    {
        responseBody = """{"status":{"value":"approved"}}""";
        await Assert.ThrowsAsync<JsonException>(Authorize);
    }

    private Task<AuthorizationOutcome> Authorize() => Authorize("ORD-1", new Money(10m, "USD"));

    private async Task<AuthorizationOutcome> Authorize(string reference, Money amount)
    {
        var gateway = new HttpPaymentGateway(client);
        var call = gateway.AuthorizeAsync(reference, amount, CancellationToken.None);
        var context = await listener.GetContextAsync();
        var request = context.Request;
        method = request.HttpMethod;
        path = request.Url!.AbsolutePath;
        contentType = request.ContentType;
        using (var reader = new StreamReader(request.InputStream, request.ContentEncoding))
            body = await reader.ReadToEndAsync();

        var bytes = Encoding.UTF8.GetBytes(responseBody);
        context.Response.StatusCode = statusCode;
        context.Response.ContentType = "application/json";
        context.Response.ContentLength64 = bytes.Length;
        await context.Response.OutputStream.WriteAsync(bytes);
        context.Response.Close();
        return await call;
    }

    private static int FreePort()
    {
        var tcp = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0);
        tcp.Start();
        var port = ((IPEndPoint)tcp.LocalEndpoint).Port;
        tcp.Stop();
        return port;
    }

    public void Dispose()
    {
        client.Dispose();
        listener.Close();
    }
}
